import type { Note } from '../../../schema/note'

/**
 * Planhat calls notes "Conversations".
 *
 * Fields are the ones in the Conversation property table and the "Get
 * conversations List" example at
 * https://www.planhat.com/developers/api/conversation:
 *   "description string Description of the conversation."
 *   "companyId Yes objectId Related company id (planhat identifier)."
 *   "createDate string ISO date when conversation was created. (Autogenerated)."
 *   "users array Array of user objects."
 *   example: "createDate":"2021-07-29T17:21:52.347Z",
 *            "users":[ { "id":"58e231b14246fc73139f29e8","name":"Alex","isOwner":true } ]
 *
 * Not mapped: `contact_id`. `endusers` is documented as "Array of involved
 * contacts (endusers ids)", but the example returns objects
 * ("endusers":[ { "id":"610091916d643a7c418aef42","name":"Lara Croft" } ]) and a
 * conversation can involve several, so there is no single documented contact.
 * `updated_at`: no update timestamp is documented. Both stay in metadata.
 */
export interface RawPlanhatNote {
  _id: string
  description?: string
  companyId?: string
  users?: Array<{ id?: string; name?: string; isOwner?: boolean }>
  createDate?: string
  [key: string]: unknown
}

export function transformNote(raw: RawPlanhatNote): Note {
  return {
    id: raw._id,
    // Required canonically; the second list example ("subject":"t6") has no description.
    content: raw.description ?? '',
    company_id: raw.companyId,
    owner_id: raw.users?.find((u) => u.isOwner === true)?.id,
    created_at: raw.createDate,
    metadata: raw,
  }
}

export function untransformNote(data: Partial<Note>): Record<string, unknown> {
  const out: Record<string, unknown> = {}
  if (data.content !== undefined) out.description = data.content
  if (data.contact_id !== undefined) out.enduserId = data.contact_id
  if (data.company_id !== undefined) out.companyId = data.company_id
  if (data.owner_id !== undefined) out.ownerId = data.owner_id
  return out
}
